typedef struct O62MBootClockModel {
    uint32_t values[O62M_BOOT_CLOCK_COUNT];
} O62MBootClockModel;

static inline void o62m_boot_clock_create(O62MBootClockModel *m, uint32_t seed)
{
    for (size_t i = 0; i < O62M_BOOT_CLOCK_COUNT; i++) {
        m->values[i] = seed;
    }
}

static inline int o62m_boot_clock_index(uint32_t address)
{
    for (size_t i = 0; i < O62M_BOOT_CLOCK_COUNT; i++) {
        if (o62m_boot_clock_defs[i].address == address) {
            return (int)i;
        }
    }
    return -1;
}

static inline bool o62m_boot_clock_read(const O62MBootClockModel *m,
                                       uint32_t address, uint32_t *value)
{
    int i = o62m_boot_clock_index(address);
    if (i < 0) { return false; }
    *value = m->values[i];
    return true;
}

static inline bool o62m_boot_clock_write(O62MBootClockModel *m,
                                        uint32_t address, uint32_t value)
{
    int i = o62m_boot_clock_index(address);
    if (i < 0 || ((m->values[i] ^ value) & ~o62m_boot_clock_defs[i].mask)) {
        return false;
    }
    m->values[i] = value;
    return true;
}

static inline uint32_t o62m_boot_clock_field(uint32_t value, uint8_t shift,
                                            uint8_t width)
{
    return width ? (value >> shift) & ((1u << width) - 1) : 0;
}

static inline bool o62m_boot_clock_gate_enabled(const O62MBootClockModel *m, size_t i)
{
    return (m->values[i] >> o62m_boot_clock_defs[i].gate_bit) & 1;
}

static inline bool o62m_boot_clock_autocg_enabled(const O62MBootClockModel *m, size_t i)
{
    return !((m->values[i] >> o62m_boot_clock_defs[i].auto_disable_bit) & 1);
}

static inline uint32_t o62m_boot_clock_source(const O62MBootClockModel *m, size_t i)
{
    const O62MBootClockDef *d = &o62m_boot_clock_defs[i];
    return o62m_boot_clock_field(m->values[i], d->source_shift, d->source_width);
}

static inline uint32_t o62m_boot_clock_divisor(const O62MBootClockModel *m, size_t i)
{
    const O62MBootClockDef *d = &o62m_boot_clock_defs[i];
    return 1 + o62m_boot_clock_field(m->values[i], d->divider_shift, d->divider_width);
}
